  int64_t *data = (int64_t *)instrumented_hthread_malloc(rank, sizeof(int64_t) * 20, 1);
  int64_t *result = (int64_t *)instrumented_hthread_malloc(rank, sizeof(int64_t) * 2, 2);
  for (int i = 0; i < 20; ++i) {
    data[i] = i;
    cpu_result += i;
  }

